const pageNames = {dashboard:['运行中心','主画面'],'run-status':['运行中心','运行状态'],points:['预测点管理','预测点列表'],'point-config':['预测点管理','点参数配置'],'weather-dashboard':['数据查询','气象预测总览'],'weather-input':['数据查询','天气输入曲线'],'weather-results':['数据查询','气象预测结果'],'weather-evaluation':['数据查询','气象误差评估'],'energy-input':['数据查询','能源输入曲线'],results:['数据查询','预测结果'],'meteo-observations':['气象预测','本地观测管理'],'nwp-config':['气象预测','NWP资料配置'],'weather-run':['气象预测','气象预测运行'],'task-config':['预测任务','任务配置'],'manual-run':['预测任务','人工启动'],'auto-schedule':['预测任务','自动定时预测'],'model-training':['模型管理','模型离线训练'],'model-update':['模型管理','模型滚动更新'],history:['预测任务','历史运行'],evaluation:['结果管理','预测结果后评估'],'system-settings':['系统设置','数据源与模型']};

function $(selector, root=document){return root.querySelector(selector)}
function $all(selector, root=document){return [...root.querySelectorAll(selector)]}
function escapeHtml(value){return String(value ?? '').replace(/[&<>'"]/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function num(value, digits=1){return Number(value || 0).toLocaleString('zh-CN',{maximumFractionDigits:digits,minimumFractionDigits:digits})}
function toast(message, error=false){const node=document.createElement('div');node.className=`toast${error?' error':''}`;node.textContent=message;$('#toastRegion').append(node);setTimeout(()=>node.remove(),3600)}

async function savePoint(point){const data=await postJSON('/api/points',point);localStorage.setItem('forecast-hmi-points',JSON.stringify(state.points));return data.point}
function savePoints(){localStorage.setItem('forecast-hmi-points',JSON.stringify(state.points));}
function loadPoints(){try{const saved=JSON.parse(localStorage.getItem('forecast-hmi-points'));if(Array.isArray(saved)&&saved.length)state.points=saved}catch(_){/* use defaults */}}
async function loadPointsFromDb(){
  const data=await getJSON('/api/points',null);
  if(data?.points?.length){state.points=data.points;state.selectedPoint=state.points.some(p=>p.id===state.selectedPoint)?state.selectedPoint:state.points[0].id;fillPointSelects();fillTrainingPointSelects();renderPointGrid();renderPointConfig(state.selectedPoint);renderHealth();renderManualRun();renderTaskTable()}
}
async function loadObjectsFromDb(){
  const data=await getJSON('/api/objects',null);
  if(data?.objects?.length){state.objects=data.objects;fillObjectSelects();fillTrainingPointSelects();renderManualRun()}
}
async function loadRunsFromDb(){
  const data=await getJSON('/api/runs?limit=20',null);
  if(!data?.runs?.length)return;
  state.runRecords=data.runs;
  state.runs=data.runs.map(run=>({id:run.run_id,point:pointById(run.point_id)?.name||run.point_id,horizon:horizonNames[run.horizon]||run.horizon,time:run.started_at?fmtTime(run.started_at):'—',duration:'—',status:run.status==='success'?'成功':run.status==='failed'?'失败':'已受理'}));
  renderRunTable();renderHistory();
}
function fillTrainingPointSelects(){
  const objectHtml=state.objects.filter(o=>o.enabled!==false).map(o=>`<option value="${escapeHtml(o.object_id)}">${escapeHtml(o.object_name)} · ${escapeHtml(o.object_type)} · ${escapeHtml(o.object_id)}</option>`).join('');
  $all('select.training-object').forEach(s=>{const before=s.value;s.innerHTML=objectHtml;s.value=state.objects.some(o=>o.object_id===before)?before:(state.objects[0]?.object_id||'')});
  const schedule=$('#scheduleObject');
  if(schedule){const all=state.objects.filter(o=>o.enabled!==false).map(o=>o.object_id);const selected=schedule.value;schedule.innerHTML=`<option value="${escapeHtml(all.join(','))}">全部默认对象</option>`+objectHtml;schedule.value=selected||all.join(',')}
}
async function postJSON(path,payload){const response=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await response.json();if(!response.ok)throw new Error(data.error||'请求失败');return data}
async function loadModels(){const data=await getJSON('/api/models?limit=50',{models:[]});const body=$('#modelTable');if(body)body.innerHTML=(data.models||[]).map(m=>{const object=objectById(m.object_id);return `<tr><td>${escapeHtml(m.version)}</td><td>${escapeHtml(object?.object_name||m.object_id||pointById(m.point_id)?.name||m.point_id||'全局')}</td><td>${escapeHtml(m.model_type||m.target_kind)}</td><td>${horizonNames[m.horizon]||m.horizon}</td><td>${m.metrics?.pv_power_kw?.sample_count||'—'}</td><td>${fmtTime(m.updated_at)}</td><td><span class="status-pill ${m.status==='active'?'success':'failed'}">${m.status==='active'?'启用':m.status}</span></td></tr>`}).join('')||'<tr><td colspan="7">暂无模型版本</td></tr>'}
async function loadModelUpdates(){const data=await getJSON('/api/model-updates?limit=50',{updates:[]});const body=$('#updateTable');if(body)body.innerHTML=(data.updates||[]).map(u=>`<tr><td>${fmtTime(u.created_at)}</td><td>${escapeHtml(u.model_id)}</td><td>${escapeHtml(objectById(u.object_id)?.object_name||u.object_id||pointById(u.point_id)?.name||u.point_id||'全局')}</td><td>${u.window_size||'—'}</td><td>${u.sample_count||0}</td><td><span class="status-pill ${u.status==='success'?'success':'failed'}">${u.status==='success'?'成功':u.status}</span></td></tr>`).join('')||'<tr><td colspan="6">暂无滚动更新记录</td></tr>'}
async function loadSchedules(){const data=await getJSON('/api/schedules',{schedules:[]});const schedules=data.schedules||[];const defaultSchedule=schedules.find(s=>s.schedule_id==='SCH-DEFAULT-DAY-AHEAD')||schedules[0];if(defaultSchedule){if($('#defaultHorizon'))$('#defaultHorizon').value=defaultSchedule.horizon;if($('#autoSchedule'))$('#autoSchedule').checked=defaultSchedule.enabled}const uiSchedule=schedules.find(s=>s.schedule_id.startsWith('SCH-UI-'))||defaultSchedule;if(uiSchedule){const objectIds=uiSchedule.object_ids?.length?uiSchedule.object_ids:(uiSchedule.point_ids||[]).flatMap(pointId=>state.objects.filter(o=>o.point_id===pointId).map(o=>o.object_id));if($('#scheduleName'))$('#scheduleName').value=uiSchedule.name||'';if($('#scheduleObject'))$('#scheduleObject').value=objectIds.join(',');if($('#scheduleKind'))$('#scheduleKind').value=uiSchedule.forecast_kind;if($('#scheduleHorizon'))$('#scheduleHorizon').value=uiSchedule.horizon;if($('#scheduleCadence'))$('#scheduleCadence').value=uiSchedule.cadence_minutes||1440;if($('#scheduleEnabled'))$('#scheduleEnabled').checked=uiSchedule.enabled;if($('#scheduleNextRun'))$('#scheduleNextRun').value=uiSchedule.next_run_at?new Date(uiSchedule.next_run_at).toISOString().slice(0,16):''}const body=$('#scheduleTable');if(body)body.innerHTML=schedules.map(s=>{const names=(s.object_ids||[]).map(id=>escapeHtml(objectById(id)?.object_name||id));const fallback=(s.point_ids||[]).map(id=>escapeHtml(pointById(id)?.name||id));return `<tr><td>${escapeHtml(s.name)}</td><td>${horizonNames[s.horizon]||s.horizon}</td><td>${(names.length?names:fallback).join('、')}</td><td>${s.cadence_minutes} 分钟</td><td>${s.next_run_at?fmtTime(s.next_run_at):'—'}</td><td>${s.last_run_at?fmtTime(s.last_run_at):'—'}</td><td><span class="status-pill ${s.enabled?'success':'failed'}">${s.enabled?'已启用':'已停用'}</span></td></tr>`}).join('')||'<tr><td colspan="7">暂无定时任务</td></tr>'}
async function loadEvaluations(){const data=await getJSON('/api/evaluations?limit=50',{evaluations:[]});const rows=data.evaluations||[];const body=$('#evaluationTable');if(body)body.innerHTML=rows.map(e=>`<tr><td>${escapeHtml(e.evaluation_id)}</td><td>${escapeHtml(e.run_id)}</td><td>${escapeHtml(pointById(e.point_id)?.name||e.point_id||'—')}</td><td>${horizonNames[e.horizon]||e.horizon}</td><td>${e.sample_count}</td><td>${e.mae==null?'—':num(e.mae,3)}</td><td>${e.rmse==null?'—':num(e.rmse,3)}</td><td>${e.bias==null?'—':num(e.bias,3)}</td><td><span class="status-pill ${e.status==='success'?'success':e.status==='pending'?'running':'failed'}">${e.status==='success'?'完成':e.status==='pending'?'待实测':'失败'}</span></td></tr>`).join('')||'<tr><td colspan="9">暂无评估记录</td></tr>';const metric=$('#evaluationMetricGrid');if(metric){const latest=rows[0]||{};metric.innerHTML=[['最近样本数',latest.sample_count||0,'对齐实测点'],['MAE',latest.mae==null?'—':num(latest.mae,3),'平均绝对误差'],['RMSE',latest.rmse==null?'—':num(latest.rmse,3),'均方根误差'],['评估状态',latest.status==='success'?'完成':latest.status==='pending'?'待实测':'—','结果后评估']].map(x=>`<div class="weather-metric-card"><span>${x[0]}</span><b>${x[1]}</b><small>${x[2]}</small></div>`).join('')}}
async function loadSystemSettings(){const data=await getJSON('/api/settings',{settings:{}});const s=data.settings||{};const local=$('[data-setting="localInterface"]'),energy=$('[data-setting="energyModel"]'),load=$('[data-setting="loadModel"]');if(s.weatherSource)$('#weatherSource').value=s.weatherSource;if(s.localInterface&&local)local.value=s.localInterface;if(s.biasWindow)$('#biasWindow').value=s.biasWindow;if(s.energyModel&&energy)energy.value=s.energyModel;if(s.loadModel&&load)load.value=s.loadModel}
function pointById(id){return state.points.find(p=>p.id===id)||state.points[0]}
function fillPointSelects(){
  const html=state.points.map(p=>`<option value="${p.id}">${escapeHtml(p.name)} · ${p.id}</option>`).join('');
  $all('select').filter(s=>s.classList.contains('query-point')||s.id==='dashPointSelect').forEach(s=>{const before=s.value;s.innerHTML=html;s.value=state.points.some(p=>p.id===before)?before:state.selectedPoint});
  $('#dashPointSelect').value=state.selectedPoint;
}
function objectById(id){return state.objects.find(o=>o.object_id===id)||state.objects[0]}
function fillObjectSelects(){
  const html=state.objects.filter(o=>o.enabled!==false).map(o=>`<option value="${escapeHtml(o.object_id)}">${escapeHtml(o.object_name)} · ${escapeHtml(o.object_type)} · ${escapeHtml(o.object_id)}</option>`).join('');
  ['#dashPointSelect','#resultObject'].forEach(selector=>{const select=$(selector);if(select){const before=select.value;select.innerHTML=html;select.value=state.objects.some(o=>o.object_id===before)?before:(state.objects[0]?.object_id||'')}})
}
function setView(view){
  const target=pageNames[view]?view:'dashboard';
  $all('.view').forEach(el=>el.classList.toggle('active',el.dataset.page===target));
  $all('.nav-item').forEach(el=>el.classList.toggle('active',el.dataset.view===target));
  $('#breadcrumbRoot').textContent=pageNames[target][0];$('#breadcrumbLeaf').textContent=pageNames[target][1];
  if(target==='points')renderPointGrid();
  if(target==='point-config')renderPointConfig(state.selectedPoint);
  if(target==='run-status')renderStatus();
  if(target==='task-config')renderTaskTable();
  if(target==='manual-run')renderManualRun();
  if(target==='history')renderHistory();
  if(target==='auto-schedule'){fillTrainingPointSelects();loadSchedules()}
  if(target==='model-training'){fillTrainingPointSelects();loadModels()}
  if(target==='model-update'){fillTrainingPointSelects();loadModelUpdates()}
  if(target==='evaluation')loadEvaluations();
  if(target==='system-settings'){renderSources();loadSystemSettings()}
  if(target==='weather-dashboard')renderWeatherDashboard();
  if(target==='weather-results')queryWeatherResults();
  if(target==='weather-evaluation')renderWeatherEvaluation();
  if(target==='meteo-observations')renderMeteoObservations();
  if(target==='nwp-config')renderNwpConfig();
  window.scrollTo({top:0,behavior:'smooth'});
}

function makeDemoRows(count=672){
  const rows=[];const start=new Date();start.setMinutes(Math.floor(start.getMinutes()/15)*15,0,0);
  for(let i=0;i<count;i++){
    const date=new Date(start.getTime()+i*15*60000), hour=date.getHours()+date.getMinutes()/60, day=date.getDay();
    const daylight=Math.max(0,Math.sin(Math.PI*(hour-6)/12));const cycle=Math.sin(i/28);const evening=Math.max(0,Math.sin(Math.PI*(hour-15)/10));
    rows.push({timestamp:date.toISOString(),wind_speed_mps:Math.max(0,5.4+1.3*Math.sin(i/47)+.45*Math.cos(i/11)),temperature_c:17+7*Math.sin(2*Math.PI*(hour-8)/24)+1.2*Math.sin(i/140),solar_radiation_wm2:Math.round(780*daylight*(.85+.12*Math.sin(i/80))),pv_power_kw:Math.max(0,92*daylight*(.88+.1*Math.sin(i/66))),wind_power_kw:Math.max(0,25+8*cycle+3*Math.cos(i/19)),load_kw:Math.max(0,66+11*evening+8*Math.sin(2*Math.PI*(hour-7)/24)+3*Math.cos(i/35)),source:'NWP + 本地校正'});
  }return rows;
}
async function getJSON(path, fallback){try{const response=await fetch(path);if(!response.ok)throw new Error('API');return await response.json()}catch(_){return fallback}}
async function getForecast(horizon='day_ahead',point=state.selectedPoint,objectId=null){const count={hour_ahead:4,ultrashort:16,day_ahead:96,week_ahead:672}[horizon]||96;const fallback={rows:makeDemoRows(count),point_id:point,object_id:objectId,horizon};const query=objectId?`object_id=${encodeURIComponent(objectId)}`:`point_id=${encodeURIComponent(point)}`;const data=await getJSON(`/api/forecast?${query}&horizon=${horizon}`,fallback);return data.rows?.length?data.rows:fallback.rows}
async function getWeatherObservations(point=state.selectedPoint){const data=await getJSON(`/api/weather-observations?point_id=${encodeURIComponent(point)}&limit=96`,{observations:[]});return (data.observations||[]).map(row=>({...row,timestamp:row.timestamp_utc,source:row.source||'本地采集'})).reverse()}
async function getEnergyMeasurements(point=state.selectedPoint){const data=await getJSON(`/api/energy-measurements?point_id=${encodeURIComponent(point)}&limit=96`,{measurements:[]});return (data.measurements||[]).map(row=>({...row,timestamp:row.timestamp_utc,source:row.source||'本地采集'})).reverse()}

function renderLineChart(svg,rows,specs){
  if(!svg)return;const width=1100,height=360,pad={l:43,r:20,t:18,b:31};svg.innerHTML='';if(!rows.length)return;
  const ns='http://www.w3.org/2000/svg';const x=i=>pad.l+(width-pad.l-pad.r)*(i/Math.max(1,rows.length-1));
  const bg=document.createElementNS(ns,'rect');bg.setAttribute('x',0);bg.setAttribute('y',0);bg.setAttribute('width',width);bg.setAttribute('height',height);bg.setAttribute('fill','transparent');svg.append(bg);
  for(let i=0;i<5;i++){const y=pad.t+(height-pad.t-pad.b)*i/4;const line=document.createElementNS(ns,'line');line.setAttribute('x1',pad.l);line.setAttribute('x2',width-pad.r);line.setAttribute('y1',y);line.setAttribute('y2',y);line.setAttribute('stroke','#1d344b');line.setAttribute('stroke-dasharray','3 5');svg.append(line);const label=document.createElementNS(ns,'text');label.setAttribute('x',7);label.setAttribute('y',y+4);label.setAttribute('fill','#5f7c95');label.setAttribute('font-size','10');label.textContent=i===0?'峰值':i===4?'0':'';svg.append(label)}
  const xLabels=[0,Math.floor(rows.length/3),Math.floor(rows.length*2/3),rows.length-1];xLabels.forEach(i=>{const label=document.createElementNS(ns,'text');label.setAttribute('x',x(i));label.setAttribute('y',height-8);label.setAttribute('fill','#607d96');label.setAttribute('font-size','10');label.setAttribute('text-anchor',i===0?'start':i===rows.length-1?'end':'middle');label.textContent=new Date(rows[i].timestamp).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});svg.append(label)});
  specs.forEach(spec=>{const values=rows.map(r=>Number(r[spec.key]||0));const min=Math.min(...values),max=Math.max(...values),range=max-min||1;const d=values.map((v,i)=>`${i?'L':'M'} ${x(i).toFixed(2)} ${(pad.t+(height-pad.t-pad.b)*(1-(v-min)/range)).toFixed(2)}`).join(' ');const path=document.createElementNS(ns,'path');path.setAttribute('d',d);path.setAttribute('fill','none');path.setAttribute('stroke',spec.color);path.setAttribute('stroke-width','2.1');path.setAttribute('stroke-linejoin','round');path.setAttribute('stroke-linecap','round');svg.append(path)});
}
function spark(element,rows,key){if(!element)return;const values=rows.map(r=>Number(r[key]||0));const min=Math.min(...values),max=Math.max(...values),range=max-min||1;const pts=values.map((v,i)=>`${(i/(values.length-1||1)*100).toFixed(1)}% ${(100-(v-min)/range*75-12).toFixed(1)}%`).join(',');element.style.clipPath=`polygon(${pts}, 100% 100%, 0 100%)`}
function metricSpecs(kind,metric){const all={weather:[['wind_speed_mps','风速','var(--cyan)'],['temperature_c','温度','var(--violet)'],['solar_radiation_wm2','太阳辐射','var(--amber)']],energy:[['pv_power_kw','光伏','var(--cyan)'],['wind_power_kw','风电','var(--amber)'],['load_kw','负荷','var(--violet)']],results:[['pv_power_kw','光伏','var(--cyan)'],['wind_power_kw','风电','var(--amber)'],['load_kw','负荷','var(--violet)']]};let list=all[kind]||all.results;if(metric&&metric!=='all')list=list.filter(x=>x[0]===metric);return list.map(x=>({key:x[0],label:x[1],color:x[2]}))}
function renderLegend(id,specs){const node=$(id);if(node)node.innerHTML=specs.map(s=>`<span><i class="legend-line" style="background:${s.color}"></i>${s.label}</span>`).join('')}

async function refreshDashboard(){const rows=await getForecast('day_ahead');state.currentRows=rows;const first=rows[0]||{};$('#kpiPv').textContent=num(first.pv_power_kw);$('#kpiWind').textContent=num(first.wind_power_kw);$('#kpiLoad').textContent=num(first.load_kw);const coverage=(Number(first.pv_power_kw||0)+Number(first.wind_power_kw||0))/Math.max(1,Number(first.load_kw||1))*100;$('#kpiCoverage').textContent=`${num(Math.min(100,coverage),1)}%`;$('#coverageBar').style.width=`${Math.min(100,coverage)}%`;spark($('#sparkPv'),rows,'pv_power_kw');spark($('#sparkWind'),rows,'wind_power_kw');spark($('#sparkLoad'),rows,'load_kw');renderLineChart($('#weatherChart'),rows.slice(0,96),metricSpecs('weather'));renderLineChart($('#powerChart'),rows,metricSpecs('results'));renderHealth();renderRunTable();$('#lastSync').textContent='刚刚'}
function renderHealth(){const el=$('#healthList');if(!el)return;el.innerHTML=state.points.map(p=>`<div class="health-row"><i></i><div><b>${escapeHtml(p.name)}</b><small>${p.type} · 最后采集 ${p.lastRun}</small></div><span class="health-value">${p.quality}</span></div>`).join('')}
function renderRunTable(){const body=$('#runTable');if(!body)return;body.innerHTML=state.runs.slice(0,4).map(r=>`<tr><td>${r.id}</td><td>${escapeHtml(r.point)}</td><td>${r.horizon}</td><td>${r.time}</td><td>${r.duration}</td><td><span class="status-pill ${r.status==='成功'?'success':r.status==='运行中'?'running':'failed'}">${r.status}</span></td></tr>`).join('')}
function renderPointGrid(){const el=$('#pointGrid');if(!el)return;el.innerHTML=state.points.map(p=>`<article class="point-card"><div class="point-card-top"><div><h3>${escapeHtml(p.name)}</h3><p>${p.id} · ${p.type}</p></div><span class="point-status">${p.enabled?'运行中':'已停用'}</span></div><div class="point-meta"><div><span>坐标</span><b>${p.lat.toFixed(3)}, ${p.lon.toFixed(3)}</b></div><div><span>容量</span><b>${num(p.pv+p.wind,0)} kW</b></div><div><span>预测对象</span><b>${p.objects.map(o=>({pv:'光伏',wind:'风电',load:'负荷'}[o])).join(' / ')}</b></div><div><span>数据质量</span><b>${p.quality}</b></div></div><div class="point-footer"><span>上次运行 · ${p.lastRun}</span><button data-edit-point="${p.id}">编辑参数 →</button></div></article>`).join('')||'<div class="empty">暂无预测点</div>'}
