function csvCell(value){const text=String(value??'');return /[",\n]/.test(text)?`"${text.replace(/"/g,'""')}"`:text}
function exportCurrentRows(){
  const rows=state.currentRows||[];
  if(!rows.length){toast('当前没有可导出的数据',true);return}
  const page=$('.view.active')?.dataset.page||'results';
  const columns=page.includes('weather')?['timestamp','wind_speed_mps','temperature_c','solar_radiation_wm2','source']:['timestamp','pv_power_kw','wind_power_kw','load_kw','source'];
  const labels={timestamp:'时间',wind_speed_mps:'风速(m/s)',temperature_c:'温度(°C)',solar_radiation_wm2:'太阳辐射(W/m²)',pv_power_kw:'光伏(kW)',wind_power_kw:'风电(kW)',load_kw:'负荷(kW)',source:'来源'};
  const csv='\uFEFF'+[columns.map(key=>labels[key]||key),...rows.map(row=>columns.map(key=>csvCell(row[key])))] .map(line=>line.join(',')).join('\n');
  const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`forecast-${page}-${new Date().toISOString().slice(0,19).replace(/[:T]/g,'-')}.csv`;link.click();URL.revokeObjectURL(url);toast(`已导出 ${rows.length} 个 15 分钟点`)
}
